      IF bs_9(to_integer(608 - sub_cast_28)) = '1' THEN 
        a1_8 := a1_8 OR mask_8;
      ELSE 
        a1_8 := a1_8 AND ( NOT mask_8);
      END IF;
    END LOOP;

    data_src0Addr_tmp <= a1_8;
    data_src1Addr_tmp <= a1_7;
    data_dstAddr_tmp <= a1_6;
    data_exponent_tmp <= a1_5;
    data_exponentIn1_tmp <= a1_4;
    data_exponentIn2_tmp <= a1_3;
    data_reluValue_tmp <= a1_2;
    data_reluScaleExp_tmp <= a1_1;
    data_single2Int8Exp_tmp <= a1_0;
    data_int82SingleExp_tmp <= a1;
  END PROCESS fromFixed_output;


  data_src0Addr <= std_logic_vector(data_src0Addr_tmp);

  data_src1Addr <= std_logic_vector(data_src1Addr_tmp);

  data_dstAddr <= std_logic_vector(data_dstAddr_tmp);

